(2873547, 400606, 12733, '<td valign="top">Funny how some cloth and cotton can arouse so much emotion.</td>', 'Funny how some cloth and cotton can arouse so much emotion.', '2006-09-28 18:26:08.000000', NULL, 1),
(2873550, 401731, 43565, '<td valign="top">I think this might be more interesting had you removed the photo and sign.  I would like to see this cropped with only the fans standing up showing so the shapes would become more important.  Also, for this challenge I think purple should be the prominent color.  I see the purple fan first, but it is a little overblown and my eyes then move to the red fans.</td>', 'I think this might be more interesting had you removed the photo and sign.  I would like to see this cropped with only the fans standing up showing so the shapes would become more important.  Also, for this challenge I think purple should be the prominent color.  I see the purple fan first, but it is a little overblown and my eyes then move to the red fans.', '2006-09-28 18:26:18.000000', NULL, 1),
(2873553, 400701, 43565, '<td valign="top">This seems more like a snapshot.</td>', 'This seems more like a snapshot.', '2006-09-28 18:27:03.000000', NULL, 1),
(2873554, 399886, 43565, '<td valign="top">I think this might be a good shot, but it is just too small to tell.</td>', 'I think this might be a good shot, but it is just too small to tell.', '2006-09-28 18:27:33.000000', NULL, 1),
(2873558, 401234, 12733, '<td valign="top">Maybe it''s my monitor, but this sure looks redder than any purple I''ve ever seen!</td>', 'Maybe it''s my monitor, but this sure looks redder than any purple I''ve ever seen!', '2006-09-28 18:29:32.000000', NULL, 1),
(2873561, 400810, 12733, '<td valign="top">Nice clear closeup, beautiful colors.</td>', 'Nice clear closeup, beautiful colors.', '2006-09-28 18:30:06.000000', NULL, 1),
(2873562, 399214, 66195, '<td valign="top">I like the composition of your photograph. However, the colors more likely resemble blue tones. I do not see purple.</td>', 'I like the composition of your photograph. However, the colors more likely resemble blue tones. I do not see purple.', '2006-09-28 18:31:17.000000', NULL, 1),
(2873563, 400785, 12733, '<td valign="top">You need to use the full allowable resolution - or at least no less than what it takes to fill the screen top to bottom - to get enough detail to really judge the shot.</td>', 'You need to use the full allowable resolution - or at least no less than what it takes to fill the screen top to bottom - to get enough detail to really judge the shot.', '2006-09-28 18:31:34.000000', NULL, 1),
(2873566, 401880, 66195, '<td valign="top">I like the composition of your photograph. However, the colors more likely resemble pink tones. I do not see purple in the subject.</td>', 'I like the composition of your photograph. However, the colors more likely resemble pink tones. I do not see purple in the subject.', '2006-09-28 18:32:50.000000', NULL, 1),
(2873569, 401694, 12733, '<td valign="top">Very cute image, and nicely rendered.</td>', 'Very cute image, and nicely rendered.', '2006-09-28 18:33:03.000000', NULL, 1),
(2873571, 401748, 12733, '<td valign="top">Brilliant colors, what is it?</td>', 'Brilliant colors, what is it?', '2006-09-28 18:34:05.000000', NULL, 1),
(2873572, 401875, 66195, '<td valign="top">I like the composition of your photograph. However, the colors more likely resemble pink tones. I do not see purple in the subject.</td>', 'I like the composition of your photograph. However, the colors more likely resemble pink tones. I do not see purple in the subject.', '2006-09-28 18:34:18.000000', NULL, 1),
(2873578, 402119, 66195, '<td valign="top">I like the composition of your photograph. However, the colors more likely resemble orange tones. I do not see purple in the subject.</td>', 'I like the composition of your photograph. However, the colors more likely resemble orange tones. I do not see purple in the subject.', '2006-09-28 18:36:44.000000', NULL, 1),
(2873584, 399159, 12733, '<td valign="top">cute</td>', 'cute', '2006-09-28 18:40:24.000000', NULL, 1),
(2873589, 400750, 12733, '<td valign="top">The bee is lucky that plant is not carnivorous!!!!</td>', 'The bee is lucky that plant is not carnivorous!!!!', '2006-09-28 18:42:38.000000', NULL, 1),
(2873596, 402033, 12733, '<td valign="top">Funny how the right lighting and coloring can make even a polluting factory complex look beautiful.</td>', 'Funny how the right lighting and coloring can make even a polluting factory complex look beautiful.', '2006-09-28 18:45:29.000000', NULL, 1),
(2873597, 399229, 12733, '<td valign="top">That heavy border reduces the amount of detail the photo can carry and is distracting.</td>', 'That heavy border reduces the amount of detail the photo can carry and is distracting.', '2006-09-28 18:46:46.000000', NULL, 1),
(2873600, 401582, 66195, '<td valign="top">I like the composition of your photograph. However, the colors more likely resemble pink tones. I do not see purple in the subject. The photograph is still beautiful. I vote a 6.</td>', 'I like the composition of your photograph. However, the colors more likely resemble pink tones. I do not see purple in the subject. The photograph is still beautiful. I vote a 6.', '2006-09-28 18:47:53.000000', NULL, 1),
(2873604, 398693, 66195, '<td valign="top">I like the composition of your photograph. However, the colors more likely resemble pink tones. I do not see purple in the subject. The photograph is still beautiful. I vote an 8.</td>', 'I like the composition of your photograph. However, the colors more likely resemble pink tones. I do not see purple in the subject. The photograph is still beautiful. I vote an 8.', '2006-09-28 18:48:36.000000', NULL, 1),
(2873605, 401068, 66195, '<td valign="top">I like the composition of your photograph. However, the colors more likely resemble blue tones. I do not see purple in the subject. The photograph is still beautiful. I vote a 7.</td>', 'I like the composition of your photograph. However, the colors more likely resemble blue tones. I do not see purple in the subject. The photograph is still beautiful. I vote a 7.', '2006-09-28 18:49:22.000000', NULL, 1),
(2873610, 401991, 58610, '<td valign="top">Awsome texture.</td>', 'Awsome texture.', '2006-09-28 18:51:09.000000', NULL, 1),
(2873615, 399229, 58610, '<td valign="top">Very nice composition.</td>', 'Very nice composition.', '2006-09-28 18:53:52.000000', NULL, 1),
(2873620, 399190, 58610, '<td valign="top">And that is EXACTLY what it looks like! Bee satisfied.</td>', 'And that is EXACTLY what it looks like! Bee satisfied.', '2006-09-28 18:55:17.000000', NULL, 1),
(2873629, 399836, 58610, '<td valign="top">I love the concept, but find myself wishing for more texture. I want the purple to JUMP OUT at me.</td>', 'I love the concept, but find myself wishing for more texture. I want the purple to JUMP OUT at me.', '2006-09-28 18:58:12.000000', NULL, 1),
(2873641, 402200, 66310, '<td valign="top">Very nice job with this. I know how difficult these types of shots can be.</td>', 'Very nice job with this. I know how difficult these types of shots can be.', '2006-09-28 19:06:03.000000', NULL, 1),
(2873642, 400647, 66310, '<td valign="top">Love the silhouette with the perfect color!</td>', 'Love the silhouette with the perfect color!', '2006-09-28 19:06:29.000000', NULL, 1),
(2873648, 399876, 66310, '<td valign="top">Excellent composition and colors!!</td>', 'Excellent composition and colors!!', '2006-09-28 19:11:08.000000', NULL, 1),
(2873677, 400893, 61818, '<td valign="top">Decent composition, meets challenge.  Front side of the flower is out of focus which greatly detracts from the shot.  Good luck!</td>', 'Decent composition, meets challenge.  Front side of the flower is out of focus which greatly detracts from the shot.  Good luck!', '2006-09-28 19:26:42.000000', NULL, 1),
(2873683, 399878, 61818, '<td valign="top">Don''t think making the whole cart purple worked very well here.  It''s just an overwhelming blob, slightly of center against a drab background.  Just the wheels?  Just the logs sticking out the front?  Perhaps selecting one or a few elements of the wagon would have been more appealing though perhaps impractical under basic edit.  Good luck!</td>', 'Don''t think making the whole cart purple worked very well here.  It''s just an overwhelming blob, slightly of center against a drab background.  Just the wheels?  Just the logs sticking out the front?  Perhaps selecting one or a few elements of the wagon would have been more appealing though perhaps impractical under basic edit.  Good luck!', '2006-09-28 19:31:11.000000', NULL, 1),
(2873687, 402270, 61818, '<td valign="top">Maybe you were going for a soft look to give some sort of hallucinogenic overtone to the shot, but it just comes across as poorly focused.  Wrinkles or creases on the background are a distraction.  Overall this is a good idea, but the shot as composed doesn''t make me think of a hendrixesque rock and roll guitarist.  Good luck!</td>', 'Maybe you were going for a soft look to give some sort of hallucinogenic overtone to the shot, but it just comes across as poorly focused.  Wrinkles or creases on the background are a distraction.  Overall this is a good idea, but the shot as composed doesn''t make me think of a hendrixesque rock and roll guitarist.  Good luck!', '2006-09-28 19:33:18.000000', NULL, 1),
(2873698, 402047, 61818, '<td valign="top">This is one of the cooler flower shots in the challenge.  Couple of issues.  First and foremost, it begs for noise reduction.  There''s a lot of noise visible on the petals.  Reducing that would smooth the petals out a bit and probably enhance what could be a more significant glow coming from that white bit in the middle.  A minor distraction is the lower right hand corner which is the only part of the photo not showing that rich purple color.  Good luck!</td>', 'This is one of the cooler flower shots in the challenge.  Couple of issues.  First and foremost, it begs for noise reduction.  There''s a lot of noise visible on the petals.  Reducing that would smooth the petals out a bit and probably enhance what could be a more significant glow coming from that white bit in the middle.  A minor distraction is the lower right hand corner which is the only part of the photo not showing that rich purple color.  Good luck!', '2006-09-28 19:39:48.000000', NULL, 1),
(2873701, 402261, 59470, '<td valign="top">HELLO!  wow - who are <i>you</i>? :-)</td>', 'HELLO!  wow - who are you? :-)', '2006-09-28 19:41:38.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2873704, 401157, 61818, '<td valign="top">This challenge is dominated by flower shots so you are up against a lot of competition.  I''m afraid this shot doesn''t fare very well in that regard.  The flash lighting is a bit harsh here giving this the look of a snapshot and flattening the flowers.  This might work a bit better cropped to just show the two flowers on the left or the group on the right.  As it is, there is no real composition and, again, it gives the feel of something taken while walking down the sidewalk with camera in hand.  Good luck!</td>', 'This challenge is dominated by flower shots so you are up against a lot of competition.  I''m afraid this shot doesn''t fare very well in that regard.  The flash lighting is a bit harsh here giving this the look of a snapshot and flattening the flowers.  This might work a bit better cropped to just show the two flowers on the left or the group on the right.  As it is, there is no real composition and, again, it gives the feel of something taken while walking down the sidewalk with camera in hand.  Good luck!', '2006-09-28 19:42:09.000000', NULL, 1),
(2873707, 402210, 59470, '<td valign="top">nice composition!  IMO would be better w/o the clutter in the background</td>', 'nice composition!  IMO would be better w/o the clutter in the background', '2006-09-28 19:43:33.000000', NULL, 1),
(2873708, 401994, 61818, '<td valign="top">I''m a sucker for pretty girls and this one is certainly easy on the eyes.  The crop here is a bit tight.  I want to see her hair flowing out on that purple background beneath her.  Also the bit of floor showing in the upper left is no good.  Overall, not too bad.  At least there''s no flower in it!  Good luck.</td>', 'I''m a sucker for pretty girls and this one is certainly easy on the eyes.  The crop here is a bit tight.  I want to see her hair flowing out on that purple background beneath her.  Also the bit of floor showing in the upper left is no good.  Overall, not too bad.  At least there''s no flower in it!  Good luck.', '2006-09-28 19:43:35.000000', NULL, 1),
(2873715, 401047, 66195, '<td valign="top">Precious photo for you to cherish for years to come. I vote 9.</td>', 'Precious photo for you to cherish for years to come. I vote 9.', '2006-09-28 19:45:26.000000', NULL, 1),
(2873716, 401770, 59470, '<td valign="top">Cool effect!!</td>', 'Cool effect!!', '2006-09-28 19:46:24.000000', NULL, 1),
(2873718, 401068, 61818, '<td valign="top">This isn''t a bad contender among the other five thousand flowers in the challenge.  Colors are nice and natural and the water drops add a bit of eye candy.  Think a slightly shallower DoF would have stomped out the background more and done a better job of moving my eye right to the subject group of flowers.  Good luck.</td>', 'This isn''t a bad contender among the other five thousand flowers in the challenge.  Colors are nice and natural and the water drops add a bit of eye candy.  Think a slightly shallower DoF would have stomped out the background more and done a better job of moving my eye right to the subject group of flowers.  Good luck.', '2006-09-28 19:46:53.000000', NULL, 1),
(2873721, 402137, 66195, '<td valign="top">I like the composition of your photograph. However, the colors more likely resemble pink tones. I do not see purple in the subject. The photograph is still beautiful.</td>', 'I like the composition of your photograph. However, the colors more likely resemble pink tones. I do not see purple in the subject. The photograph is still beautiful.', '2006-09-28 19:47:44.000000', NULL, 1),
(2873723, 400836, 9643, '<td valign="top">A beautiful composition</td>', 'A beautiful composition', '2006-09-28 19:48:37.000000', NULL, 1),
(2873724, 401708, 61818, '<td valign="top">I will never understand why people submit shots smaller than the maximu allowed size.  Setting that aside, this is nice crisp shot of the flower.  The bee is a bit blurry.  Parts of the upper right flower petal are overexposed (or have been blown out in processing).  The more I look at this the more I keep staring at that bee, wishing it were in better focus.  Good luck.</td>', 'I will never understand why people submit shots smaller than the maximu allowed size.  Setting that aside, this is nice crisp shot of the flower.  The bee is a bit blurry.  Parts of the upper right flower petal are overexposed (or have been blown out in processing).  The more I look at this the more I keep staring at that bee, wishing it were in better focus.  Good luck.', '2006-09-28 19:48:46.000000', NULL, 1),
(2873726, 402200, 9643, '<td valign="top">This is a delightful picture</td>', 'This is a delightful picture', '2006-09-28 19:49:09.000000', NULL, 1),
(2873730, 401045, 9643, '<td valign="top">Very nice use of contrasting color.</td>', 'Very nice use of contrasting color.', '2006-09-28 19:50:20.000000', NULL, 1),
(2873735, 401471, 61818, '<td valign="top">Awful lot of black in this photo which doesn''t really do anything for it.  The orangeish street lighting behind the car also detract from what could have looked very glossy and slick.  I see rain drops on the rear window, I''m wondering how a closeup of the droplets on a piece of glass framed by some of the purple body would have looked?  As it is, the shot doesn''t really give my eye anything to latch on to.  There are some shapes being formed by the purple lines but there is just too much other stuff going on to give those shapes a chance to jump out.  Good luck.</td>', 'Awful lot of black in this photo which doesn''t really do anything for it.  The orangeish street lighting behind the car also detract from what could have looked very glossy and slick.  I see rain drops on the rear window, I''m wondering how a closeup of the droplets on a piece of glass framed by some of the purple body would have looked?  As it is, the shot doesn''t really give my eye anything to latch on to.  There are some shapes being formed by the purple lines but there is just too much other stuff going on to give those shapes a chance to jump out.  Good luck.', '2006-09-28 19:51:27.000000', NULL, 1),
(2873738, 401751, 61818, '<td valign="top">Nicely done.  Soft lighting with a lot of interesting shapes to look at.  I think this could look even better if the ''boring'' part of the curtain on the right, where the light lines are mostly gone and the seam of the curtain dominates, were cropped out.  Good luck.</td>', 'Nicely done.  Soft lighting with a lot of interesting shapes to look at.  I think this could look even better if the ''boring'' part of the curtain on the right, where the light lines are mostly gone and the seam of the curtain dominates, were cropped out.  Good luck.', '2006-09-28 19:53:05.000000', NULL, 1),
(2873746, 401899, 61818, '<td valign="top">This doesn''t work for me.  Great looking girl, great crop, well shot - then you colored her purple.  It''s just unsettling.  Lips, fingernails, sunglasses - little bits and pieces purple would have worked well but the whole thing inked out in shades of purple just isn''t doing it for me.  Nice concept though.  Good luck.</td>', 'This doesn''t work for me.  Great looking girl, great crop, well shot - then you colored her purple.  It''s just unsettling.  Lips, fingernails, sunglasses - little bits and pieces purple would have worked well but the whole thing inked out in shades of purple just isn''t doing it for me.  Nice concept though.  Good luck.', '2006-09-28 19:55:38.000000', NULL, 1),
(2873749, 402236, 61818, '<td valign="top">Nice idea, composition needs some work.  Rotate it so either the horizon or the horizontal bar of the cross is level.  Scoot over a little and shoot it so there isn''t that little bit of tree branch nudging its way in on the upper right.  Maybe shoot from just a bit higher?  Overall not bad, but really has a lot of potential to be even better.</td>', 'Nice idea, composition needs some work.  Rotate it so either the horizon or the horizontal bar of the cross is level.  Scoot over a little and shoot it so there isn''t that little bit of tree branch nudging its way in on the upper right.  Maybe shoot from just a bit higher?  Overall not bad, but really has a lot of potential to be even better.', '2006-09-28 19:57:57.000000', NULL, 1),
(2873755, 402105, 61818, '<td valign="top">Looks like you were trying to focus on the ants?  Not sure, but pretty much everything in this shot is out of focus with the exception of the white things jutting out of the flower.  At least the flower with the ants on it should be in focus and draw the eye in.  At the same time, there is a lot of detail to be mad eout in the background which makes for a cluttered composition.  Good luck.</td>', 'Looks like you were trying to focus on the ants?  Not sure, but pretty much everything in this shot is out of focus with the exception of the white things jutting out of the flower.  At least the flower with the ants on it should be in focus and draw the eye in.  At the same time, there is a lot of detail to be mad eout in the background which makes for a cluttered composition.  Good luck.', '2006-09-28 19:59:50.000000', NULL, 1),
(2873763, 400993, 61818, '<td valign="top">The purple berry, presumably your subject, might work just a bit better had you moved over to the side it is on and then taken the photo.  As it is, there is this large, red, out of focus branch in the way with a little bit of a berry trying to make an appearance behind it.  Good luck.</td>', 'The purple berry, presumably your subject, might work just a bit better had you moved over to the side it is on and then taken the photo.  As it is, there is this large, red, out of focus branch in the way with a little bit of a berry trying to make an appearance behind it.  Good luck.', '2006-09-28 20:01:45.000000', NULL, 1),
(2873766, 401997, 61818, '<td valign="top">Turn off the datestamp.  As you''re headed for DQ, I''ll just offer that you could back off the sharpening quite a bit.  Good luck.</td>', 'Turn off the datestamp.  As you''re headed for DQ, I''ll just offer that you could back off the sharpening quite a bit.  Good luck.', '2006-09-28 20:02:50.000000', NULL, 1),
(2873771, 399003, 61818, '<td valign="top">Looks pink to me.  Setting that aside, portions of the main flower are overexposed.  Consider a different composition as well.  Something that gives the eye something to lock on to or things to move the eye around.  This appears as a mash of pink and green locked in by black.  Oddly enough, I do see a couple of spots of purple back in those shadows.  Good luck.</td>', 'Looks pink to me.  Setting that aside, portions of the main flower are overexposed.  Consider a different composition as well.  Something that gives the eye something to lock on to or things to move the eye around.  This appears as a mash of pink and green locked in by black.  Oddly enough, I do see a couple of spots of purple back in those shadows.  Good luck.', '2006-09-28 20:04:38.000000', NULL, 1),
(2873780, 400647, 61818, '<td valign="top">This shot is very appealing up to the point where the nice purple shades fade into a very unnatural looking blue.  A tighter crop, with less ground beneath and lopping off the top where the clouds end would work much better.  Good luck.</td>', 'This shot is very appealing up to the point where the nice purple shades fade into a very unnatural looking blue.  A tighter crop, with less ground beneath and lopping off the top where the clouds end would work much better.  Good luck.', '2006-09-28 20:06:45.000000', NULL, 1),
(2873783, 402250, 61818, '<td valign="top">nice colors, good concept.  Would work a lot better if the reflection were a bit more out of focus so that the foreground object really had a chance to jump out.  I also think it would increase the moodiness of the shot overall.  nice work and a unique entry.</td>', 'nice colors, good concept.  Would work a lot better if the reflection were a bit more out of focus so that the foreground object really had a chance to jump out.  I also think it would increase the moodiness of the shot overall.  nice work and a unique entry.', '2006-09-28 20:07:43.000000', NULL, 1),
(2873791, 400928, 61818, '<td valign="top">So rare to see an actual still life in a challenge.  Interesting composition.  Lighting could use a bit of work, and you might have made something in there that is purple a bit more prominent.  Good luck.</td>', 'So rare to see an actual still life in a challenge.  Interesting composition.  Lighting could use a bit of work, and you might have made something in there that is purple a bit more prominent.  Good luck.', '2006-09-28 20:10:21.000000', NULL, 1),
(2873794, 400705, 61818, '<td valign="top">Cropped tighter, the curves, gradients and reflections might make for a very interesting shot.  Cropped this way, I feel like I''m flipping through a catalog picking out a coffee mug to print my logo on.  Good luck.</td>', 'Cropped tighter, the curves, gradients and reflections might make for a very interesting shot.  Cropped this way, I feel like I''m flipping through a catalog picking out a coffee mug to print my logo on.  Good luck.', '2006-09-28 20:11:24.000000', NULL, 1),
(2873797, 402260, 61818, '<td valign="top">Very cool shot except for the white stem beneath.  While you can''t clone it out, orienting thing so it was at least a vertical line would help.  It completely wrecks the effect of this shot.  Great tones and shadows in the flower petals though.  Good luck.</td>', 'Very cool shot except for the white stem beneath.  While you can''t clone it out, orienting thing so it was at least a vertical line would help.  It completely wrecks the effect of this shot.  Great tones and shadows in the flower petals though.  Good luck.', '2006-09-28 20:12:55.000000', NULL, 1),
(2873801, 400993, 64086, '<td valign="top">I think this photo would be more effective if you changed the point of view to highlight and focus on the one berry.</td>', 'I think this photo would be more effective if you changed the point of view to highlight and focus on the one berry.', '2006-09-28 20:15:23.000000', NULL, 1),
(2873802, 402228, 61818, '<td valign="top">I''ve just let all sorts of reds and pinks and all other sorts of colors pass as ''might possibly be purple'' but I just can''t see purple here.  Speaking directly to the photo, it is very dark and unfortunately it appears as if you focused on the hair instead of the object in the foreground.  Good luck.</td>', 'I''ve just let all sorts of reds and pinks and all other sorts of colors pass as ''might possibly be purple'' but I just can''t see purple here.  Speaking directly to the photo, it is very dark and unfortunately it appears as if you focused on the hair instead of the object in the foreground.  Good luck.', '2006-09-28 20:15:37.000000', NULL, 1),
(2873824, 398875, 64086, '<td valign="top">The top bottle is photographed very nicely, the bottom one doesn''t add to the picture. (Maybe remove it or change the lighting.) I think bright refelection on the glass and green part of the bottom bottle seem out of character with the subtle reflections of the top one.</td>', 'The top bottle is photographed very nicely, the bottom one doesn''t add to the picture. (Maybe remove it or change the lighting.) I think bright refelection on the glass and green part of the bottom bottle seem out of character with the subtle reflections of the top one.', '2006-09-28 20:24:04.000000', NULL, 1),
(2873887, 401823, 28532, '<td valign="top">Wow - super sweet!!!  Great Shot!!</td>', 'Wow - super sweet!!!  Great Shot!!', '2006-09-28 21:02:12.000000', NULL, 1),
(2874020, 398941, 65234, '<td valign="top">Nice color but awfully dark in the center of the flower.</td>', 'Nice color but awfully dark in the center of the flower.', '2006-09-28 22:01:04.000000', NULL, 1),
(2874072, 402000, 59470, '<td valign="top">nice coloring, but it appears a little blurry</td>', 'nice coloring, but it appears a little blurry', '2006-09-28 22:23:32.000000', NULL, 1),
(2874080, 402264, 59470, '<td valign="top">very intriquing image</td>', 'very intriquing image', '2006-09-28 22:24:47.000000', NULL, 1),
(2874084, 401707, 59470, '<td valign="top">interesting idea!</td>', 'interesting idea!', '2006-09-28 22:25:12.000000', NULL, 1),
(2874089, 401595, 59470, '<td valign="top">i''d like to see a little more of the crowns and a little tighter crop on the left</td>', 'i''d like to see a little more of the crowns and a little tighter crop on the left', '2006-09-28 22:26:53.000000', NULL, 1),
(2874092, 402122, 59470, '<td valign="top">great use of the color purple!!</td>', 'great use of the color purple!!', '2006-09-28 22:27:22.000000', NULL, 1),
(2874095, 400133, 59470, '<td valign="top">i love it!</td>', 'i love it!', '2006-09-28 22:27:44.000000', NULL, 1),
(2874101, 401002, 59470, '<td valign="top">clear, crisp, good job</td>', 'clear, crisp, good job', '2006-09-28 22:28:30.000000', NULL, 1),
(2874103, 401440, 59470, '<td valign="top">great use of colors</td>', 'great use of colors', '2006-09-28 22:28:52.000000', NULL, 1),
