(2874884, 401707, 65234, '<td valign="top">It does make you think "purple!"  If the lines on the beads all pointed to the purple bead it would be even better in terms of drawing the eye.</td>', 'It does make you think "purple!"  If the lines on the beads all pointed to the purple bead it would be even better in terms of drawing the eye.', '2006-09-29 05:07:09.000000', NULL, 1),
(2874894, 402233, 61531, '<td valign="top">Beautiful and haunting, with the imperfections and fragility of the web combined with the many different variations of purple.  A truly beautiful shot.</td>', 'Beautiful and haunting, with the imperfections and fragility of the web combined with the many different variations of purple.  A truly beautiful shot.', '2006-09-29 05:19:14.000000', NULL, 1),
(2874896, 401562, 61531, '<td valign="top">I love the way the purple shines against the wall and in the pearls.  Very nicely put together.</td>', 'I love the way the purple shines against the wall and in the pearls.  Very nicely put together.', '2006-09-29 05:20:35.000000', NULL, 1),
(2874901, 401449, 61531, '<td valign="top">This really reminded me of the Where''s Waldo books of my youth.  I really enjoyed the yellow against the purple, along with the inventiveness of the shot.</td>', 'This really reminded me of the Where''s Waldo books of my youth.  I really enjoyed the yellow against the purple, along with the inventiveness of the shot.', '2006-09-29 05:24:33.000000', NULL, 1),
(2874905, 400940, 61531, '<td valign="top">Very serene and relaxing.  I could really lose myself in this picture.  Truly a beautiful piece.</td>', 'Very serene and relaxing.  I could really lose myself in this picture.  Truly a beautiful piece.', '2006-09-29 05:26:27.000000', NULL, 1),
(2874906, 401239, 61531, '<td valign="top">Very .. purple.  But really well put together.  It has a very fantasy feel to it, and all of the elements fall into place very nicely.</td>', 'Very .. purple.  But really well put together.  It has a very fantasy feel to it, and all of the elements fall into place very nicely.', '2006-09-29 05:27:34.000000', NULL, 1),
(2874908, 401833, 61531, '<td valign="top">I think I would have liked this one better if it had been a bit more vibrant and not so washed out.</td>', 'I think I would have liked this one better if it had been a bit more vibrant and not so washed out.', '2006-09-29 05:29:44.000000', NULL, 1),
(2874910, 401751, 61531, '<td valign="top">I love the way the light was captured shining through the curtains.</td>', 'I love the way the light was captured shining through the curtains.', '2006-09-29 05:30:44.000000', NULL, 1),
(2874912, 401047, 61531, '<td valign="top">Adorable! From the bare feet to the matching outfits and color.</td>', 'Adorable! From the bare feet to the matching outfits and color.', '2006-09-29 05:35:03.000000', NULL, 1),
(2874913, 400224, 27524, '<td valign="top">Despite its flower...its defenetly one of the best performances here. Your angle and focus is very creative and also beautiful. Good luck!</td>', 'Despite its flower...its defenetly one of the best performances here. Your angle and focus is very creative and also beautiful. Good luck!', '2006-09-29 05:35:13.000000', NULL, 1),
(2874915, 400606, 61531, '<td valign="top">A very poignant shot.  I love the feelings this picture creates, and the symbolism is just fantastic.</td>', 'A very poignant shot.  I love the feelings this picture creates, and the symbolism is just fantastic.', '2006-09-29 05:36:33.000000', NULL, 1),
(2874917, 401762, 27524, '<td valign="top">Very beautiful...the contrast betweel light colors and dark are stunning. She have very beautiful eys i must say. Creative, orighinal...one of top photos IMO!</td>', 'Very beautiful...the contrast betweel light colors and dark are stunning. She have very beautiful eys i must say. Creative, orighinal...one of top photos IMO!', '2006-09-29 05:37:02.000000', NULL, 1),
(2874919, 401687, 27524, '<td valign="top">Very beautiful landscape and there surely are not many of them. Real beautiful contrast of tree and purple sky.</td>', 'Very beautiful landscape and there surely are not many of them. Real beautiful contrast of tree and purple sky.', '2006-09-29 05:39:28.000000', NULL, 1),
(2874920, 400082, 27524, '<td valign="top">Simple, beautiful and different than other for sure.</td>', 'Simple, beautiful and different than other for sure.', '2006-09-29 05:39:54.000000', NULL, 1),
