INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2890002, 402256, 65756, '<td valign="top">Truly Gorgeous...</td>', 'Truly Gorgeous...', '2006-10-03 03:42:26.000000', NULL, 1),
(2890003, 401733, 65756, '<td valign="top">CAn''t wait you here how it was done...</td>', 'CAn''t wait you here how it was done...', '2006-10-03 03:43:19.000000', NULL, 1),
(2890060, 401234, 44611, '<td valign="top">Great shot - there''s a wonderful delicacy about it.   Good composition, but sadly this looks totally pink on my monitor not purple at all.</td>', 'Great shot - there''s a wonderful delicacy about it.   Good composition, but sadly this looks totally pink on my monitor not purple at all.', '2006-10-03 04:20:09.000000', NULL, 1),
(2890064, 402227, 44611, '<td valign="top">A great idea and at least a more innovative take on purple flowers.  I have some bugs with this though, mostly the uneveness of the crop.  Having gone for a central composiiton, I wish the space to left and right were equal and I think, too, that this may have benefited from more neutral space above the flowers.</td>', 'A great idea and at least a more innovative take on purple flowers.  I have some bugs with this though, mostly the uneveness of the crop.  Having gone for a central composiiton, I wish the space to left and right were equal and I think, too, that this may have benefited from more neutral space above the flowers.', '2006-10-03 04:22:38.000000', NULL, 1),
(2890073, 399952, 44611, '<td valign="top">A great idea and distinctly purple.  I wish the focus were sharper - if it had I think this would have been a very high scoring shot.</td>', 'A great idea and distinctly purple.  I wish the focus were sharper - if it had I think this would have been a very high scoring shot.', '2006-10-03 04:30:01.000000', NULL, 1),
(2890076, 399460, 44611, '<td valign="top">Lovely composition and colours.  Seems quite grainy which may have been deliberate, but I''m not sure it enhances the image.  Shame about the dust spots too, but hey, this was basic editing.</td>', 'Lovely composition and colours.  Seems quite grainy which may have been deliberate, but I''m not sure it enhances the image.  Shame about the dust spots too, but hey, this was basic editing.', '2006-10-03 04:33:20.000000', NULL, 1),
(2890099, 402220, 49578, '<td valign="top">The frame is too vertical IMO</td>', 'The frame is too vertical IMO', '2006-10-03 04:47:59.000000', NULL, 1),
(2890126, 401762, 49578, '<td valign="top">frankly, i do not like the mask, it takes away a lot from those beautiful eyes and the lovely smooth skin</td>', 'frankly, i do not like the mask, it takes away a lot from those beautiful eyes and the lovely smooth skin', '2006-10-03 05:09:29.000000', NULL, 1),
(2890438, 402201, 64035, '<td valign="top">I like the quality (especially the sharpness) and texture of this image, but I''m not fond of the d-sat.</td>', 'I like the quality (especially the sharpness) and texture of this image, but I''m not fond of the d-sat.', '2006-10-03 08:07:54.000000', NULL, 1),
(2890440, 401829, 64035, '<td valign="top">I found this a bit difficult to rate, as it''s a very "left field" image. On balance, I think it''s a better idea than it is a photograph - the composition feels random and the lighting is average. However, there''s nothing else like it in the challenge, and that''s good. And it is visually shocking.</td>', 'I found this a bit difficult to rate, as it''s a very "left field" image. On balance, I think it''s a better idea than it is a photograph - the composition feels random and the lighting is average. However, there''s nothing else like it in the challenge, and that''s good. And it is visually shocking.', '2006-10-03 08:09:40.000000', NULL, 1),
(2890443, 400937, 64035, '<td valign="top">Great texture, great composition. Excellent.</td>', 'Great texture, great composition. Excellent.', '2006-10-03 08:11:00.000000', NULL, 1),
(2890449, 400470, 64035, '<td valign="top">I know from the title that you''ve tried to bring the car in as a feature, but I thought about it and in the end decided it just looked like a defect in an otherwise unremarkable image. It''s a pretty church though.</td>', 'I know from the title that you''ve tried to bring the car in as a feature, but I thought about it and in the end decided it just looked like a defect in an otherwise unremarkable image. It''s a pretty church though.', '2006-10-03 08:15:57.000000', NULL, 1),
(2890451, 399886, 64035, '<td valign="top">Nothing wrong with the photo, but way way too small, I''m afraid.</td>', 'Nothing wrong with the photo, but way way too small, I''m afraid.', '2006-10-03 08:16:23.000000', NULL, 1),
(2890456, 399793, 64035, '<td valign="top">This is different. Which is sometimes good, sometimes bad. In this case, it just didn''t work for me. I couldn''t find a message, or even really an emotion.</td>', 'This is different. Which is sometimes good, sometimes bad. In this case, it just didn''t work for me. I couldn''t find a message, or even really an emotion.', '2006-10-03 08:17:26.000000', NULL, 1),
(2890458, 401879, 64035, '<td valign="top">Not a horrible image, in fact, quite a nice idea. Just way too small, I''m afraid.</td>', 'Not a horrible image, in fact, quite a nice idea. Just way too small, I''m afraid.', '2006-10-03 08:17:59.000000', NULL, 1),
(2890460, 399346, 64035, '<td valign="top">The focus on this image is way too loose - the pen, for example, is really blurred. Also, it felt a bit like you just took a random photo and made it purple.</td>', 'The focus on this image is way too loose - the pen, for example, is really blurred. Also, it felt a bit like you just took a random photo and made it purple.', '2006-10-03 08:19:01.000000', NULL, 1),
(2890465, 401449, 64035, '<td valign="top">I quite like the idea of the "where''s wally" style find-the-bee, but the rest of the image is just unremarkable, and the out-of-field flowers to the left serve as a distraction rather than a feature.</td>', 'I quite like the idea of the "where''s wally" style find-the-bee, but the rest of the image is just unremarkable, and the out-of-field flowers to the left serve as a distraction rather than a feature.', '2006-10-03 08:20:49.000000', NULL, 1),
(2890468, 400766, 64035, '<td valign="top">There are an awful lot of flower shots in this challenge, and unfortunately this one is a little unremarkable. The seperation from the background isn''t quite good enough, and the light is non-ideal - I''d prefer to see the flower less dark.</td>', 'There are an awful lot of flower shots in this challenge, and unfortunately this one is a little unremarkable. The seperation from the background isn''t quite good enough, and the light is non-ideal - I''d prefer to see the flower less dark.', '2006-10-03 08:21:59.000000', NULL, 1),
(2890472, 399190, 64035, '<td valign="top">Aside from the (irrelevant) "is this really purple" argument, the problem is that the flowers in the background just serve as an immense distraction. It would be a better image if we were closer to the insect.</td>', 'Aside from the (irrelevant) "is this really purple" argument, the problem is that the flowers in the background just serve as an immense distraction. It would be a better image if we were closer to the insect.', '2006-10-03 08:23:07.000000', NULL, 1),
(2890474, 401939, 64035, '<td valign="top">Sometimes there can be nothing "wrong" with an image, but it just doesn''t work for me as a viewer, and this is unfortunately one of those times. I just really hate the white soft surround</td>', 'Sometimes there can be nothing "wrong" with an image, but it just doesn''t work for me as a viewer, and this is unfortunately one of those times. I just really hate the white soft surround', '2006-10-03 08:24:24.000000', NULL, 1),
(2890479, 400166, 64035, '<td valign="top">I dislike "angle" images to begin with, and the actual content is unremarkable, I''m afraid. It doesn''t really feel composed at all, just a bit of a snapshot.</td>', 'I dislike "angle" images to begin with, and the actual content is unremarkable, I''m afraid. It doesn''t really feel composed at all, just a bit of a snapshot.', '2006-10-03 08:26:09.000000', NULL, 1),
(2890482, 400785, 64035, '<td valign="top">This isn''t a bad idea, it''s just too small and the image quality (especially around your face (not your face itself, the detail and colours)) isn''t up to scratch.</td>', 'This isn''t a bad idea, it''s just too small and the image quality (especially around your face (not your face itself, the detail and colours)) isn''t up to scratch.', '2006-10-03 08:27:44.000000', NULL, 1),
(2890485, 402118, 64035, '<td valign="top">The "flower" entries in this challenge are a fiercely competitive area, and you need to do something a little special to stand out. Unfortunately, this image, while pleasant enough, is unremarkable. It feels too confused and busy - there are too many flowers.</td>', 'The "flower" entries in this challenge are a fiercely competitive area, and you need to do something a little special to stand out. Unfortunately, this image, while pleasant enough, is unremarkable. It feels too confused and busy - there are too many flowers.', '2006-10-03 08:28:50.000000', NULL, 1),
(2890487, 400502, 64035, '<td valign="top">It''s different. I like the idea. But it somehow fails to be sexy, or appealing. The ultra-shallow depth of field is often a good idea, but in this case it rather takes away the shape of the figure, and I find that unattractive.</td>', 'It''s different. I like the idea. But it somehow fails to be sexy, or appealing. The ultra-shallow depth of field is often a good idea, but in this case it rather takes away the shape of the figure, and I find that unattractive.', '2006-10-03 08:30:21.000000', NULL, 1),
(2890492, 402204, 64035, '<td valign="top">I really like this image, and the way it plays with the Wizard of Oz. It could, perhaps, be slightly more interestingly lit, but the two purples work well together. Well done!</td>', 'I really like this image, and the way it plays with the Wizard of Oz. It could, perhaps, be slightly more interestingly lit, but the two purples work well together. Well done!', '2006-10-03 08:32:48.000000', NULL, 1),
(2890494, 401239, 64035, '<td valign="top">This is an oddly disturbing and powerful image, beautifully lit, shot and composed. I''m particularly fond of the model''s left hand, and the way her index finger is just barely visible. It has a strong visual impact, and the quality is superb. Top mark.</td>', 'This is an oddly disturbing and powerful image, beautifully lit, shot and composed. I''m particularly fond of the model''s left hand, and the way her index finger is just barely visible. It has a strong visual impact, and the quality is superb. Top mark.', '2006-10-03 08:34:08.000000', NULL, 1),
(2890497, 401762, 64035, '<td valign="top">This is a lovely portrait, and the eyes in particular are beautiful. One mild commen - it is possible (I think) to see the camera in the reflection. Not much of a flaw in an otherwise flawless photo.</td>', 'This is a lovely portrait, and the eyes in particular are beautiful. One mild commen - it is possible (I think) to see the camera in the reflection. Not much of a flaw in an otherwise flawless photo.', '2006-10-03 08:35:18.000000', NULL, 1),
(2890510, 401694, 2978, '<td valign="top">Simply beautiful</td>', 'Simply beautiful', '2006-10-03 08:42:29.000000', NULL, 1),
(2890514, 402261, 66494, '<td valign="top">where''s the purple?</td>', 'where''s the purple?', '2006-10-03 08:49:19.000000', NULL, 1),
