(2896038, 402196, 30637, '<td valign="top">Thanks to all who commented. This was tightly cropped from the following image:<br/> <br/><img alt="'' . substr(''//i107.photobucket.com/albums/m286/noellasue/IMG_5713aa.jpg'', strrpos(''//i107.photobucket.com/albums/m286/noellasue/IMG_5713aa.jpg'', ''/'') + 1) . ''" border="0" src="//i107.photobucket.com/albums/m286/noellasue/IMG_5713aa.jpg"/></td>', 'Thanks to all who commented. This was tightly cropped from the following image: ', '2006-10-04 14:29:12.000000', NULL, 0),
