(2898231, 401874, 43298, '<td valign="top">Super Cool! This is awesome!</td>', 'Super Cool! This is awesome!', '2006-10-05 00:19:29.000000', NULL, 0),
(2898381, 399014, 60862, '<td valign="top">Hey, Judy.  I feel honored to have outscored you by a full TWO TEN THOUSANDTHS of a point. ;)<br/> <br/>Lessee - I got loads more 1-3s, but then again, I doubled your total of 10s.  Snort.<br/> <br/>Oh.  A comment on your shot.  Right.<br/> <br/>It''s very pretty. :)  I think a little deeper DOF so everything was sharp, and you''d have a much higher score.  Whereas not much could improve my shot, other than not submitting it.</td>', 'Hey, Judy.  I feel honored to have outscored you by a full TWO TEN THOUSANDTHS of a point. ;) Lessee - I got loads more 1-3s, but then again, I doubled your total of 10s.  Snort. Oh.  A comment on your shot.  Right. It''s very pretty. :)  I think a little deeper DOF so everything was sharp, and you''d have a much higher score.  Whereas not much could improve my shot, other than not submitting it.', '2006-10-05 01:00:16.000000', NULL, 0),
(2898517, 399876, 42013, '<td valign="top">I would like to see a page devoted to ribboning Cannon Beach shots. Congrats on the retina searing quality of this pic. Dont care for the bird FWIW, and is suspect you might have cropped it out if cropping wouldn''t removed the seastacks dome. Congrats!</td>', 'I would like to see a page devoted to ribboning Cannon Beach shots. Congrats on the retina searing quality of this pic. Dont care for the bird FWIW, and is suspect you might have cropped it out if cropping wouldn''t removed the seastacks dome. Congrats!', '2006-10-05 01:52:49.000000', NULL, 0),
(2898571, 399876, 61336, '<td valign="top">Congrats on your ribbon. Couldn''t believe you did not mess with the colors. Magnificent photo. Definitely worth the blue.</td>', 'Congrats on your ribbon. Couldn''t believe you did not mess with the colors. Magnificent photo. Definitely worth the blue.', '2006-10-05 02:19:20.000000', NULL, 0),
